"""Source-backed stack ownership of literal actor-name prefixes in NPC orders."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0x682A,0x6830,'data','Testo degli ordini NPC: prefisso, comando composto e chiusura'),(0xA59F,0xA5CD,'code','Ingresso pubblico del testo e stack degli argomenti'),(0xA720,0xA771,'code','Nome dell’attore e chiamate relative dei testi'),(0xA7C5,0xA7D0,'code','Descrittore del nome: ponte al renderer di entità'),(0xD3E8,0xD448,'code','Nome composto: prefissi e sostantivo finale con scarico differito'),(0xA95B,0xA990,'code','Decoder dei candidati: scrittore alternativo del medesimo stack'),(0xC388,0xC3E4,'code','Glifo: righe e registri salvati; proprietà del byte alto 5D1F'),(0xCE10,0xCE18,'code','Ordine NPC: stampa 682A dopo aver registrato la richiesta')]
notes={0x682A:'Dati del linguaggio dei testi: chiama 6804, compone l’ordine, chiude la citazione e la frase. 6804 chiama 67F7 con il nome dell’attore. Non disassemblare come istruzioni CPU.',0xA59F:'Nel percorso naturale CE13 l’ingresso pubblico ha SP=5D78. I salvataggi e le chiamate annidate determinano il frame del nome: non è un valore casuale costante.',0xA5B6:'Il return link A5B9, le due invocazioni 682A -> 6804 -> 67F7 e la stampa del nome portano il prefisso del nome proprio al frame C388=5D2A.',0xA75B:'Token CALL relativo: salva IX e invoca A5C4. I due livelli 682A -> 6804 -> 67F7 fanno parte del calcolo del frame.',0xA755:'Il nome dell’attore passa dal descrittore A4BC ad A7C5/D3E8. Il prefisso viene scaricato mentre il renderer di nome è attivo.',0xD438:'Emette il sostantivo finale; resta nel buffer fino al delimitatore successivo, dopo il ritorno da D3E8. Non ha lo stesso frame del prefisso.',0xD416:'Primo qualificatore del nome: viene emesso prima del secondo qualificatore e del sostantivo. Nel percorso verificato Inspector si scarica al delimitatore del nome Lestrade.',0xA97C:'CALL A990 salva il proprio return link. Con un altro chiamante questo può sovrascrivere 5D1F: il byte non appartiene sempre al renderer.',0xC388:'Frame d’ingresso variabile. Le prove ABI indipendenti coprono sette frame, inclusi 5D24 e 5D2A, tre caratteri e tre colonne.',0xC38B:'Il salvataggio dell’indirizzo video scrive l’alto a frame-7. Con frame 5D26 sarebbe 5D1F; non confonderlo con una riga del font.',0xC39C:'Salva B/C per ogni scansione; l’ultimo passaggio conserva B=1. Con frame 5D28 B raggiunge 5D1F.',0xC39D:'Salva AF della riga del font non ancora allineata. L’ultima riga resta a frame-11: con frame 5D2A il byte 5D1F è glyph[7], che può essere diverso da zero.',0xCE10:'Richiesta già registrata: il testo visualizzato deriva dall’ordine effettivo, non da una sequenza di risposte catturata.',0xCE13:'L’ordine di Lestrade al cocchiere a tick 964 è l’ultimo scrittore naturale individuato prima della lettura casuale a tick 2491.'}
fields={0xC388:[['5D1F','1 byte, proprietà condizionata','Frame 5D2A: ultima riga non allineata del glifo. Altri frame/caller richiedono una provenienza distinta'],['Ordine NPC','CE13 / 682A','Prefisso del nome proprio del nome: proprietà verificata. Nomi di dizionario e altre stampe revocano il nuovo byte'],['5D1A–5D1E','non proiettati dal nuovo contratto','Non riempiti estendendo arbitrariamente il limite del renderer']],0x682A:[['682A','dati compressi','Chiamata 6804; composizione dell’ordine; virgoletta; termine frase']]}
lines=['; Dossier offline: i byte sono riassellati contro il payload, non eseguiti nel runtime JS.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/upper-stack';root.mkdir(exist_ok=True)
(root/'upper-stack.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=89,**({'fields':fields[a]}if a in fields else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
